"table": null,
"explanation": "<ruby>答<rt>こた</rt></ruby>えは 24<ruby>分後<rt>ぷんご</rt></ruby> です。\n<ruby>両方<rt>りょうほう</rt></ruby>が<ruby>同時<rt>どうじ</rt></ruby>に<ruby>発車<rt>はっしゃ</rt></ruby>するのは、8の<ruby>倍数<rt>ばいすう</rt></ruby>でも12の<ruby>倍数<rt>ばいすう</rt></ruby>でもある<ruby>時刻<rt>じこく</rt></ruby>です。つまり8と12の<ruby>公倍数<rt>こうばいすう</rt></ruby>を<ruby>考<rt>かんが</rt></ruby>えます。\n8の<ruby>倍数<rt>ばいすう</rt></ruby>は 8, 16, 24, 32 ...、12の<ruby>倍数<rt>ばいすう</rt></ruby>は 12, 24, 36 ... です。\n<ruby>共通<rt>きょうつう</rt></ruby>するいちばん<ruby>小<rt>ちい</rt></ruby>さい<ruby>数<rt>かず</rt></ruby>は24なので、<ruby>次<rt>つぎ</rt></ruby>に<ruby>同時<rt>どうじ</rt></ruby>になるのは24<ruby>分後<rt>ぷんご</rt></ruby>です。\n8 × 12 = 96 として96<ruby>分後<rt>ぷんご</rt></ruby>とするまちがいが<ruby>多<rt>おお</rt></ruby>いですが、じっさいはそれより<ruby>早<rt>はや</rt></ruby>く<ruby>重<rt>かさ</rt></ruby>なります。\nポイント: <ruby>次<rt>つぎ</rt></ruby>に<ruby>同時<rt>どうじ</rt></ruby>になる<ruby>時<rt>とき</rt></ruby>は<ruby>最小公倍数<rt>さいしょうこうばいすう</rt></ruby>で<ruby>求<rt>もと</rt></ruby>めます。"
