"explanation": "<ruby>答<rt>こた</rt></ruby>えは 6<ruby>本<rt>ぽん</rt></ruby>できて 0.3 L あまる です。\n7.5 ÷ 1.2 を<ruby>計算<rt>けいさん</rt></ruby>します。わる<ruby>数<rt>かず</rt></ruby>を<ruby>整数<rt>せいすう</rt></ruby>にするため、どちらも10<ruby>倍<rt>ばい</rt></ruby>して 75 ÷ 12 と<ruby>考<rt>かんが</rt></ruby>えます。\n75 ÷ 12 は 6 あまり 3 になりますが、あまりはもとの<ruby>位<rt>くらい</rt></ruby>にもどす<ruby>必要<rt>ひつよう</rt></ruby>があります。\nあまりは10<ruby>倍<rt>ばい</rt></ruby>したままの<ruby>数<rt>かず</rt></ruby>なので、3 を10<ruby>分<rt>ぶん</rt></ruby>の1にして 0.3 L です。\nたしかめると 1.2 × 6 = 7.2、7.5 − 7.2 = 0.3 となり<ruby>合<rt>あ</rt></ruby>っています。\nポイント: <ruby>商<rt>しょう</rt></ruby>はそのまま、あまりだけもとの<ruby>小数点<rt>しょうすうてん</rt></ruby>の<ruby>位置<rt>いち</rt></ruby>にもどします。"
