"question": "<ruby>先月<rt>せんげつ</rt></ruby>の<ruby>電気代<rt>でんきだい</rt></ruby>は 4000 <ruby>円<rt>えん</rt></ruby>、<ruby>今月<rt>こんげつ</rt></ruby>は 3000 <ruby>円<rt>えん</rt></ruby>でした。<ruby>今月<rt>こんげつ</rt></ruby>の<ruby>電気代<rt>でんきだい</rt></ruby>は、<ruby>先月<rt>せんげつ</rt></ruby>の<ruby>何倍<rt>なんばい</rt></ruby>ですか。それ<ruby>以上<rt>いじょう</rt></ruby><ruby>約分<rt>やくぶん</rt></ruby>できない<ruby>分数<rt>ぶんすう</rt></ruby>で<ruby>答<rt>こた</rt></ruby>えましょう。",
