"topic": "対応する角",
"level": 1,
"question": "<ruby>四角形<rt>しかくけい</rt></ruby>ABCDと<ruby>四角形<rt>しかくけい</rt></ruby>EFGHは<ruby>合同<rt>ごうどう</rt></ruby>で、<ruby>頂点<rt>ちょうてん</rt></ruby>AとE、BとF、CとG、DとHが<ruby>対応<rt>たいおう</rt></ruby>しています。<ruby>四角形<rt>しかくけい</rt></ruby>ABCDの<ruby>角<rt>かく</rt></ruby>Cの<ruby>大<rt>おお</rt></ruby>きさが115°のとき、<ruby>角<rt>かく</rt></ruby>Gの<ruby>大<rt>おお</rt></ruby>きさは<ruby>何<rt>なん</rt></ruby><ruby>度<rt>ど</rt></ruby>ですか。",
