"explanation": "<ruby>答<rt>こた</rt></ruby>えは 32cm<sup>2</sup> です。\n<ruby>台形<rt>だいけい</rt></ruby>の<ruby>面積<rt>めんせき</rt></ruby>は「(<ruby>上底<rt>じょうてい</rt></ruby>+<ruby>下底<rt>かてい</rt></ruby>)×<ruby>高<rt>たか</rt></ruby>さ÷2」で<ruby>求<rt>もと</rt></ruby>めます。\n6+10=16、16×4=64、64÷2=32 なので、<ruby>面積<rt>めんせき</rt></ruby>は32cm<sup>2</sup>です。\n÷2をわすれて64cm<sup>2</sup>としたり、<ruby>上底<rt>じょうてい</rt></ruby>と<ruby>下底<rt>かてい</rt></ruby>をたさずに<ruby>計算<rt>けいさん</rt></ruby>したりしないように<ruby>気<rt>き</rt></ruby>をつけましょう。\nポイント: <ruby>上底<rt>じょうてい</rt></ruby>と<ruby>下底<rt>かてい</rt></ruby>をたしてから<ruby>高<rt>たか</rt></ruby>さをかけ、<ruby>最後<rt>さいご</rt></ruby>に÷2します。"
