"question": "2<ruby>本<rt>ほん</rt></ruby>の<ruby>対角線<rt>たいかくせん</rt></ruby>の<ruby>長<rt>なが</rt></ruby>さが8cmと6cmのひし<ruby>形<rt>がた</rt></ruby>の<ruby>面積<rt>めんせき</rt></ruby>は<ruby>何<rt>なん</rt></ruby>cm<sup>2</sup>ですか。",
