"unit": "e5_u11",
"topic": "立方体の体積",
"level": 1,
"question": "1<ruby>辺<rt>ぺん</rt></ruby>が9cmの<ruby>立方体<rt>りっぽうたい</rt></ruby>の<ruby>形<rt>かたち</rt></ruby>をした<ruby>小物入<rt>こものい</rt></ruby>れがあります。この<ruby>小物入<rt>こものい</rt></ruby>れの<ruby>体積<rt>たいせき</rt></ruby>は<ruby>何<rt>なん</rt></ruby>cm<sup>3</sup> ですか。",
