"explanation": "<ruby>答<rt>こた</rt></ruby>えは <ruby>時速<rt>じそく</rt></ruby>60km です。\n<ruby>速<rt>はや</rt></ruby>さは 「<ruby>道<rt>みち</rt></ruby>のり ÷ <ruby>時間<rt>じかん</rt></ruby>」 で<ruby>求<rt>もと</rt></ruby>めます。\n180 ÷ 3 = 60 なので、1<ruby>時間<rt>じかん</rt></ruby>あたり 60km <ruby>進<rt>すす</rt></ruby>む<ruby>速<rt>はや</rt></ruby>さです。\nかけ<ruby>算<rt>ざん</rt></ruby>にして 180 × 3 = 540 とすると、3<ruby>時間<rt>じかん</rt></ruby>で<ruby>走<rt>はし</rt></ruby>った<ruby>道<rt>みち</rt></ruby>のりよりずっと<ruby>大<rt>おお</rt></ruby>きな<ruby>数<rt>かず</rt></ruby>になってしまいます。\n<ruby>時速<rt>じそく</rt></ruby>90km は 2<ruby>時間<rt>じかん</rt></ruby>で<ruby>走<rt>はし</rt></ruby>ったときの<ruby>速<rt>はや</rt></ruby>さなので、<ruby>時間<rt>じかん</rt></ruby>の<ruby>数<rt>かず</rt></ruby>を<ruby>読<rt>よ</rt></ruby>みまちがえないようにします。\nポイント: <ruby>速<rt>はや</rt></ruby>さは 1<ruby>時間<rt>じかん</rt></ruby>あたりに<ruby>進<rt>すす</rt></ruby>む<ruby>道<rt>みち</rt></ruby>のりです。"
