"question": "<ruby>地域<rt>ちいき</rt></ruby>の<ruby>清掃<rt>せいそう</rt></ruby>に<ruby>参加<rt>さんか</rt></ruby>した40<ruby>人<rt>にん</rt></ruby>のうち、30<ruby>代<rt>だい</rt></ruby>の<ruby>人<rt>ひと</rt></ruby>は10<ruby>人<rt>にん</rt></ruby>でした。この<ruby>結果<rt>けっか</rt></ruby>を<ruby>帯<rt>おび</rt></ruby>グラフに<ruby>表<rt>あらわ</rt></ruby>すとき、30<ruby>代<rt>だい</rt></ruby>の<ruby>部分<rt>ぶぶん</rt></ruby>は<ruby>全体<rt>ぜんたい</rt></ruby>の<ruby>何<rt>なん</rt></ruby>%になりますか。",
