"question": "アンケートの<ruby>結果<rt>けっか</rt></ruby>を<ruby>円<rt>えん</rt></ruby>グラフに<ruby>表<rt>あらわ</rt></ruby>します。<ruby>全体<rt>ぜんたい</rt></ruby>の15%にあたる<ruby>部分<rt>ぶぶん</rt></ruby>の、<ruby>中心<rt>ちゅうしん</rt></ruby>の<ruby>角<rt>かく</rt></ruby>の<ruby>大<rt>おお</rt></ruby>きさは<ruby>何<rt>なん</rt></ruby><ruby>度<rt>ど</rt></ruby>ですか。",
