"question": "<ruby>下<rt>した</rt></ruby>の<ruby>表<rt>ひょう</rt></ruby>は、<ruby>職場<rt>しょくば</rt></ruby>の40<ruby>人<rt>にん</rt></ruby>にお<ruby>昼<rt>ひる</rt></ruby>ごはんについて<ruby>聞<rt>き</rt></ruby>いた<ruby>結果<rt>けっか</rt></ruby>です。この<ruby>結果<rt>けっか</rt></ruby>を<ruby>帯<rt>おび</rt></ruby>グラフに<ruby>表<rt>あらわ</rt></ruby>すとき、「お<ruby>弁当<rt>べんとう</rt></ruby>」の<ruby>部分<rt>ぶぶん</rt></ruby>は<ruby>全体<rt>ぜんたい</rt></ruby>の<ruby>何<rt>なん</rt></ruby>%になりますか。",
