"explanation": "<ruby>答<rt>こた</rt></ruby>えは 35% です。\n<ruby>表<rt>ひょう</rt></ruby>の<ruby>人数<rt>にんずう</rt></ruby>をたすと 14+10+12+4=40(<ruby>人<rt>にん</rt></ruby>)で、これが<ruby>全体<rt>ぜんたい</rt></ruby>です。\nお<ruby>弁当<rt>べんとう</rt></ruby>は14<ruby>人<rt>にん</rt></ruby>なので、14÷40=0.35、<ruby>百分率<rt>ひゃくぶんりつ</rt></ruby>になおして35%です。\n<ruby>人数<rt>にんずう</rt></ruby>の14をそのまま14%としたり、<ruby>外食<rt>がいしょく</rt></ruby>の10<ruby>人<rt>にん</rt></ruby>ぶんの25%と<ruby>取<rt>と</rt></ruby>りちがえたりしやすいので、どの<ruby>数<rt>かず</rt></ruby>を<ruby>全体<rt>ぜんたい</rt></ruby>にするかを<ruby>先<rt>さき</rt></ruby>に<ruby>決<rt>き</rt></ruby>めましょう。\nポイント: <ruby>帯<rt>おび</rt></ruby>グラフに<ruby>表<rt>あらわ</rt></ruby>すときは、まず<ruby>合計<rt>ごうけい</rt></ruby>を<ruby>求<rt>もと</rt></ruby>めてから<ruby>割合<rt>わりあい</rt></ruby>を<ruby>計算<rt>けいさん</rt></ruby>します。"
